    for p in [(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]:
        if p in seen: continue
        st=[p]; seen.add(p); comp=[]
        while st:
            q=st.pop(); comp.append(q)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(q[0]+dr,q[1]+dc)
                    if 0<=n[0]<H and 0<=n[1]<W and n not in seen and g[n[0]][n[1]]!=bg:
                        seen.add(n); st.append(n)
        if len(comp)<2: continue
        rows=[q[0] for q in comp]; cols=[q[1] for q in comp]
